public class A40HttpMock implements HttpCalloutMock {
 public HttpResponse respond(HttpRequest req) {
  HttpResponse res=new HttpResponse(); res.setStatusCode(207);
  res.setStatus('Multi-Status'); res.setHeader('X-A40',req.getMethod());
  res.setBody(String.valueOf(req.getEndpoint())+'|'+String.valueOf(req.getBody()));
  return res;
 }
}

