@RestResource(urlMapping='/a40-oracle/*')
global class A40RestOracle {
    @HttpGet
    global static String get() {
        return RestContext.request.params.get('key');
    }

    @HttpPost
    global static String post() {
        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(
            RestContext.request.requestBody.toString());
        RestContext.response.statusCode = 201;
        return (String) body.get('value');
    }

    @HttpDelete
    global static void remove() {
        RestContext.response.statusCode = 204;
        RestContext.response.responseBody = null;
    }
}

